# P1 desk check (engine side): withMetadata(String, BsonValue) clones the metadata and puts / removes ONE key (foreign keys kept)
def _code(cls, meth, sig=None):
    from jpype import JClass
    IP = JClass("javassist.bytecode.InstructionPrinter")
    out = []
    for mm in pool.get(cls).getDeclaredMethods():
        if str(mm.getName()) != meth or (sig and sig not in str(mm.getSignature())):
            continue
        ca = mm.getMethodInfo().getCodeAttribute()
        it, cp = ca.iterator(), mm.getMethodInfo().getConstPool()
        while it.hasNext():
            out.append(str(IP.instructionString(it, it.next(), cp)))
    return out


_wm = _code(T["IS"], "withMetadata", "(Ljava/lang/String;Lorg/bson/BsonValue;)")
assert any("BsonDocument.clone" in l for l in _wm) and any("BsonDocument.put" in l for l in _wm) and any("BsonDocument.remove" in l for l in _wm), "P1: withMetadata(String, BsonValue) is no longer clone + put / remove one key"
for _m in ("withDurability", "withQuantity"):
    assert any("ItemStack.metadata" in l for l in _code(T["IS"], _m)), "P1: %s must carry the metadata document" % _m

TOKEN = re.compile(r"@([A-Z0-9]{2,7})@")


def jv(src):
    def rep(mm):
        k = mm.group(1)
        if k not in T:
            raise SystemExit("unknown token @%s@ in:\n%s" % (k, src[:300]))
        return T[k]
    return TOKEN.sub(rep, src)


def M(cls, src):
    try:
        cls.addMethod(CtNewMethod.make(jv(src), cls))
    except Exception as e:
        raise SystemExit("compile failed in %s:\n%s\n---\n%s" % (cls.getName(), e, jv(src)[:6000]))


def F(cls, src):
    try:
        cls.addField(CtField.make(jv(src), cls))
    except Exception as e:
        raise SystemExit("field failed in %s:\n%s\n---\n%s" % (cls.getName(), e, jv(src)[:600]))


def C(cls, src):
    try:
        cls.addConstructor(CtNewConstructor.make(jv(src), cls))
    except Exception as e:
        raise SystemExit("constructor failed in %s:\n%s\n---\n%s" % (cls.getName(), e, jv(src)[:2000]))


