M(cod, r"""
public static @IS@ markOut(@IS@ s, String key) {
  if (empty(s) || key == null || key.length() == 0) return s;
  org.bson.BsonDocument d = new org.bson.BsonDocument();
  d.put("p", new org.bson.BsonString(key));
  @IS@ out = s.withMetadata(OUTK, (org.bson.BsonValue) d);
  try { if (s.getOverrideDroppedItemAnimation()) out.setOverrideDroppedItemAnimation(true); } catch (Throwable t) { }
  return out;
}""")
# a copy carrying SkyyRequip = { e: eid } (withMetadata(String, BsonValue): clone + put one key - every other key kept, P1)
M(cod, r"""
public static @IS@ stamp(@IS@ s, String eid) {
  if (empty(s) || eid == null) return s;
  org.bson.BsonDocument d = new org.bson.BsonDocument();
  d.put("e", new org.bson.BsonString(eid));
  @IS@ s0 = s;
  if (outOf(s) != null) s0 = s.withMetadata(OUTK, (org.bson.BsonValue) null);   // 0.2.5: into Requip = the Take out mark is gone
  @IS@ out = s0.withMetadata(STAMP, (org.bson.BsonValue) d);
  try { if (s.getOverrideDroppedItemAnimation()) out.setOverrideDroppedItemAnimation(true); } catch (Throwable t) { }
  return out;
}""")
# a copy without the stamp (an empty metadata document left behind becomes none)
M(cod, r"""
public static @IS@ unstamp(@IS@ s) {
  if (empty(s)) return s;
  boolean st = stampOf(s) != null;
  boolean ou = outOf(s) != null;   // 0.2.5: the Take out mark goes too - every "same item?" check sees the plain item
  if (!st && !ou) return s;
  @IS@ out = s;
  if (st) out = out.withMetadata(STAMP, (org.bson.BsonValue) null);
  if (ou) out = out.withMetadata(OUTK, (org.bson.BsonValue) null);
  org.bson.BsonDocument md = out.getMetadata();
  if (md != null && md.isEmpty()) out = out.withMetadata((org.bson.BsonDocument) null);
  try { if (s.getOverrideDroppedItemAnimation()) out.setOverrideDroppedItemAnimation(true); } catch (Throwable t) { }
  return out;
}""")
