# =====================================================================================================================
# WdClass: which space an item belongs to (P2: the engine's own Item asset) - "a0".."a3" armor spot, "i" items, "-reason" refused
# =====================================================================================================================
M(klass, r"""
public static String classify(@IS@ s) {
  if (@PKG@.WdCodec.empty(s)) return "-There is nothing there.";
  String id = s.getItemId();
  if (@PKG@.WdCfg.builtinKeep(id)) return "-The Potion Flask and Food Pouch stay with you - they never go into Requip.";   // 0.2.8
  if (@PKG@.WdCfg.keep(id)) return "-The SkyWynn Menu item and the vault arrows never go into Requip.";
  if (@PKG@.WdCfg.deny(id)) return "-The server keeps this item out of Requip.";
  if (id.startsWith("Skyy_Unid_Bag_") || @PKG@.WdCodec.unid(s)) return "-Identify it first - unidentified gear stays out of Requip.";
  if (id.startsWith("Skyy_Talisman_") || id.startsWith("Skyy_Accessory_") || id.startsWith("Skyy_Acc_")) return "-Accessories go in your Accessory Bag.";
  if (id.startsWith("Skyy_Sack_") || id.startsWith("Skyy_Bag_")) return "-Bags stay out of Requip.";
  @ITEM@ it = @PKG@.WdCodec.itemOf(id);
  if (it == null) return "-The game no longer knows this item.";
  try { @ISCC@ c = it.getItemStackContainerConfig(); if (c != null && c.getCapacity() > 0) return "-Anything that holds items stays out of Requip."; } catch (Throwable t) { }
  try {
    @IARM@ a = it.getArmor();
    if (a != null && a.getArmorSlot() != null) { int o = a.getArmorSlot().ordinal(); if (o >= 0 && o < 4) return "a" + o; }
  } catch (Throwable t) { }
  if (@PKG@.WdCfg.allow(id)) return "i";
  if ((id.startsWith("Tool_") || id.startsWith("SkyyFishing_Rod_")) && @PKG@.WdCodec.maxStack(id) <= 1) return "i";   // 0.2.4: the hoe (no Tool block) + every tool tier
  if (@PKG@.WdCodec.lu(s).length() > 0) return "i";   // 0.2.4: a SkyyGear lifelong tool, whatever its item
  try { if (it.getWeapon() != null || it.getTool() != null) return "i"; } catch (Throwable t) { }
  try { if (it.isConsumable()) return "i"; } catch (Throwable t) { }
  return "-Blocks and materials go in your Magic Bags.";
}""")
