M(shop, r"""
public static String buy(@PR@ pr, @ST@ st, @REF@ ref, @PKG@.WdData d, int idx, String shown) {
  java.util.UUID u = pr.getUuid();
  if (!@PKG@.WdCfg.SLOT_BUY) return "-Buying loadout slots is switched off on this server.";
  if (d.shopBad) return "-Your bought slots could not be read - an admin has been told. Nothing is lost.";
  String fx = settle(u, d);
  if (d.pTx != null) return "-An earlier slot purchase is still being checked - try again in a moment.";
  int nx = next(u, d);
  int cap = @PKG@.WdCfg.MAX < @PKG@.WdData.MAX ? @PKG@.WdCfg.MAX : @PKG@.WdData.MAX;
  if (nx < 0) return "-There is no loadout slot to buy - " + @PKG@.WdSlots.unlocked(u, d) + " of " + cap + " are open.";
  if (idx != nx) return "-Buy the slots in order: loadout " + (nx + 1) + " is next.";
  long now = System.currentTimeMillis();
  Object lb = LASTBUY.get(u);
  if (lb instanceof Long && now >= ((Long) lb).longValue() && now - ((Long) lb).longValue() < 1500L) return "-One slot at a time - wait a moment.";
  boolean free = isFree(pr, st, ref);
  int lv = level(u, d);
  long p = free ? 0L : priceAt(lv, nx + 1);
  if (shown == null || !shown.trim().equals(String.valueOf(p))) return "=Loadout " + (nx + 1) + " now costs " + fmt(p) + " coins - press Buy again to pay that.";
  if (!d.key.equals(@PKG@.WdStore.pkey(u))) return "-Your profile changed - open Requip again.";
  // a profile whose Requip files were never written gets them first (index.json): a rollback's first-write cleanup never moves shop.json
  if (!d.exists && !@PKG@.WdStore.save(d)) return "-Could not save - nothing changed.";
  if (p <= 0L) {
    if (!write(d, d.bought + 1, -1, -1, 0L, -1L, null, 0L)) return "-Could not save - nothing changed.";
    LASTBUY.put(u, Long.valueOf(now));
    BUYS = BUYS + 1L;
    @PKG@.WdStore.log("BUY " + u + " " + d.key + " slot=" + (nx + 1) + " price=0 (" + (free ? "free: Creative / skyywardrobe.free" : "free: price 0") + ")");
    return "+Loadout " + (nx + 1) + " is open" + (free ? " (free in Creative / with permission)" : "") + ".";
  }
  if (!coinsHas()) return "-Buying slots needs SkyyCoins.";
  if (flush() < 0) return "-Your coins could not be saved just now - nothing changed, try again in a moment.";   // fix round: the purse read = the purse on disk
  long bal = balance(u);
  if (bal < 0L) return "-Your coins could not be read - try again.";
  if (bal < p) return "-Not enough coins: loadout " + (nx + 1) + " costs " + fmt(p) + ", you have " + fmt(bal) + ".";
  String tx = Long.toHexString(@PKG@.WdData.RND.nextLong() & 0x7fffffffffffffffL) + Long.toHexString(now);
  if (!write(d, d.bought, -1, nx, p, bal, tx, now)) return "-Could not save - nothing changed, no coins taken.";
  if (CRASH_AT == 1) { CRASH_AT = 0; throw new IllegalStateException("harness crash after the purchase note"); }
  if (!take(u, p)) {
    if (!write(d, d.bought, -1, -1, 0L, -1L, null, 0L)) {
      VOID.put(d.key, tx);
      @PKG@.WdLog.warn("Requip " + d.key + ": the purchase note of a refused take could not be cleared - it is VOID (never unlocks); the next check / the 30 s watch clears it");
    }
    return "-Not enough coins - nothing changed.";
  }
  if (flush() < 0) {   // fix round: SkyyCoins could not save the take - the coins go back rather than a slot a crash could make free
    boolean back0 = give(u, p);
    if (back0) {
      flush();
      REFUNDS = REFUNDS + 1L;
      if (!write(d, d.bought, -1, -1, 0L, -1L, null, 0L)) VOID.put(d.key, tx);
      @PKG@.WdStore.log("BUYFAIL " + u + " " + d.key + " slot=" + (nx + 1) + " price=" + p + " tx=" + tx + " coins not saved by SkyyCoins - refunded");
      return "-Your coins could not be saved - nothing changed (your " + fmt(p) + " coins are back).";
    }
    @PKG@.WdLog.warn("Requip " + d.key + ": SkyyCoins could not save a slot purchase and the refund failed - the slot is opened (the coins are taken in SkyyCoins' memory)");
  }
  if (CRASH_AT == 2) { CRASH_AT = 0; throw new IllegalStateException("harness crash after the take"); }
  if (!write(d, d.bought + 1, -1, -1, 0L, -1L, null, 0L)) {
    boolean back = give(u, p);
    flush();
    REFUNDS = REFUNDS + 1L;
    if (back && !write(d, d.bought, -1, -1, 0L, -1L, null, 0L)) {
      VOID.put(d.key, tx);
      @PKG@.WdLog.warn("Requip " + d.key + ": refunded, but the purchase note could not be cleared - it is VOID (never unlocks); the next check / the 30 s watch clears it");
    }
    @PKG@.WdStore.log("BUYFAIL " + u + " " + d.key + " slot=" + (nx + 1) + " price=" + p + " tx=" + tx + (back ? " refunded" : " REFUND FAILED - the note stays, the next check unlocks the slot"));
    if (!back) @PKG@.WdLog.warn("Requip " + d.key + ": a slot purchase could not be saved AND the refund of " + p + " coins failed - the note stays; the next page / join unlocks the slot (requip.log BUYFAIL)");
    return back ? "-Could not save the new slot - your " + fmt(p) + " coins were given back." : "-Could not save the new slot - it opens at your next visit (the server log has the details).";
  }
  LASTBUY.put(u, Long.valueOf(now));
  BUYS = BUYS + 1L;
  @PKG@.WdStore.log("BUY " + u + " " + d.key + " slot=" + (nx + 1) + " price=" + p + " level=" + lv + " balance " + bal + " -> " + (bal - p) + " tx=" + tx);
  return "+Loadout " + (nx + 1) + " is open - paid " + fmt(p) + " coins (price level " + lv + ")." + (fx != null ? " " + @PKG@.WdLog.body(fx) : "");
}""")
