M(tx, r"""
public static java.util.ArrayList depAllSkip(@PKG@.WdData d, @IC@[] cs, int[] secs, boolean auto, java.util.ArrayList why, java.util.HashMap keep, int heldSlot, java.util.HashMap hotKeep) {
  java.util.ArrayList out = new java.util.ArrayList();
  java.util.HashMap kinds = new java.util.HashMap();
  int[] add = new int[2];
  java.util.HashMap sup = new java.util.HashMap();   // 0.2.9: supply:fn:claims answers, one ask per id in this pass
  for (int o = 0; o < secs.length; o++) {
    int i = secs[o];
    if (i < 0 || i >= cs.length || cs[i] == null) continue;
    int cap = cs[i].getCapacity();
    for (int s = 0; s < cap; s++) {
      @IS@ x = @PKG@.WdInv.at(cs, i, s);
      if (x == null || @PKG@.WdCfg.keep(x.getItemId())) continue;
      if (auto && (!@PKG@.WdClass.unique(x) || @PKG@.WdCodec.stampOf(x) != null || !@PKG@.WdClass.ok(@PKG@.WdClass.classify(x)))) continue;
      if (auto && d.key != null && d.key.equals(@PKG@.WdCodec.outOf(x))) continue;   // 0.2.5: you took it out by hand - it stays
      if (i == 1 && s == heldSlot) continue;
      if (i == 1 && hotKeep != null && hotKeep.size() > 0) {
        String hk = kindKey(x.withQuantity(1));
        Object ho = hotKeep.get(hk);
        if (ho instanceof Integer && ((Integer) ho).intValue() > 0) { hotKeep.put(hk, Integer.valueOf(((Integer) ho).intValue() - 1)); continue; }
      }
      if (keep != null && keep.size() > 0) {
        String kk = kindKey(x.withQuantity(1));
        Object o = keep.get(kk);
        if (o instanceof Integer && ((Integer) o).intValue() > 0) { keep.put(kk, Integer.valueOf(((Integer) o).intValue() - 1)); continue; }
      }
      // 0.2.9 (FP1 review LOW): eating beats storing - a plain storage / backpack stack the Potion Flask / Food Pouch claim stays for their
      // auto-fill (as SkyySacks 0.8.18); the hotbar / metadata stacks and auto-store (never food) as before
      if (!auto && (i == 2 || i == 3) && (x.getMetadata() == null || x.getMetadata().isEmpty()) && @PKG@.WdBridge.claimed(d.uuid, x.getItemId(), sup)) {
        why.add("the Potion Flask / Food Pouch takes your " + @PKG@.WdCodec.pretty(x.getItemId()));
        continue;
      }
      @PKG@.WdMove m = depMove(d, cs, i, s, kinds, add, why);
      if (m != null) out.add(m);
    }
  }
  return out;
}""")
