M(srt, r"""
public int compare(Object x, Object y) {
  @PKG@.WdEntry a = (@PKG@.WdEntry) x;
  @PKG@.WdEntry b = (@PKG@.WdEntry) y;
  if (this.mode == 1) { int c = @PKG@.WdCodec.rIndex(b.rar) - @PKG@.WdCodec.rIndex(a.rar); if (c != 0) return c; }
  if (this.mode == 2) { int c = b.lv - a.lv; if (c != 0) return c; }
  if (a.addedAt != b.addedAt) return a.addedAt > b.addedAt ? -1 : 1;
  return a.eid.compareTo(b.eid);
}""")

