plug = cls("SkyyWardrobePlugin", T["JP"])
F(plug, "public static volatile Object TIMER = null;")
C(plug, "public SkyyWardrobePlugin(@JPI@ init) { super(init); }")
M(plug, r"""
public void setup() {
  @PKG@.WdLog.LOG = getLogger();
  java.nio.file.Path mods = getDataDirectory().getParent();
  // 0.2.2: the one-time slots.free 4 -> 10 update of an existing config.properties, BEFORE load / CfgPub.start (the kit's history + change
  // log folder and logger first; CfgPub.start sets the same again)
  try {
    @PKG@.CfgRows.LOG = getLogger();
    @PKG@.CfgRows.HOME = mods.resolve("Skyy_SkyyWardrobe");
    @PKG@.CfgHist.init();
    @PKG@.CfgLog.init();
    @PKG@.WdCfg.migFree(mods.resolve("Skyy_SkyyWardrobe").resolve("config.properties"));
  } catch (Throwable t) { @PKG@.WdLog.warn("the 0.2.2 free loadouts update was skipped: " + t); }
  @PKG@.WdCfg.load(mods);
  @PKG@.WdStore.ROOT = mods.resolve("Skyy_SkyyWardrobe");
  @PKG@.WdStore.DIR01 = @PKG@.WdStore.ROOT.resolve("loadouts");
  @PKG@.WdStore.RQ = @PKG@.WdStore.ROOT.resolve("requip");
  @PKG@.WdStore.LOGF = @PKG@.WdStore.ROOT.resolve("requip.log");
  @PKG@.WdAuto.load(@PKG@.WdStore.RQ.resolve("autostore.json"));
  int[] sc = @PKG@.WdStore.scanAll(false);
  @PKG@.CfgPub.start(mods, getLogger());
  java.util.Map br = @PKG@.WdLog.bridge();
@FNS@
  br.put("requip:stampKey", "@STAMP@");
  getCommandRegistry().registerCommand(new @PKG@.WdCmd());
  getCommandRegistry().registerCommand(new @PKG@.WdAdminCmd());
  @PKG@.WdHop.READER = java.util.concurrent.Executors.newSingleThreadScheduledExecutor(new @PKG@.WdThreads());   // 0.2.1 fixer: before the join listener
  getEventRegistry().registerGlobal(@PRE@.class, new @PKG@.WdReady());
  getEventRegistry().registerGlobal(@PDE@.class, new @PKG@.WdQuit());
  try { @HSV@.SCHEDULED_EXECUTOR.schedule(new @PKG@.WdScan(), 3L, java.util.concurrent.TimeUnit.SECONDS); }
  catch (Throwable t) { @PKG@.WdLog.warn("the Requip file check could not be scheduled: " + t); }
  try { TIMER = @HSV@.SCHEDULED_EXECUTOR.scheduleWithFixedDelay(new @PKG@.WdTimer(), 2L, 1L, java.util.concurrent.TimeUnit.SECONDS); }
  catch (Throwable t) { @PKG@.WdLog.warn("the Requip timer could not start: " + t + " - journals stay until the next start, auto-store does not run"); }
  int hubTabs = 0;
  try { hubTabs = @PKG@.WdHubOpen.register(); } catch (Throwable t5) { @PKG@.WdLog.warn("could not put the Storage > Requip hub tab: " + t5); }   // 0.2.6
  getLogger().at(java.util.logging.Level.INFO).log("[SkyyWardrobe] @VERSION@ ready - hub tab storage:requip " + (hubTabs == 1 ? "put" : "NOT put") + "; Requip: " + sc[0] + " profiles (pool files checked in the background, " + sc[2] + " journals to repair at join), " + sc[4] + " 0.1 wardrobes waiting to move in; " + @PKG@.WdCfg.summary() + "; pets " + (@PKG@.WdBridge.petsHas() ? "found" : "not loaded yet (SkyyPets 0.2.3+)") + ", abilities " + (@PKG@.WdBridge.abilHas() ? "found" : "not loaded yet (SkyyClasses 0.1.19+)") + ", pocket blocks " + (@PKG@.WdBridge.pocketHas() ? "found" : "not loaded yet (SkyySacks)") + (@PKG@.WdBridge.backHas() ? " + give-back" : "") + "; bridge wardrobe:fn:open|canDeposit|depositSlot|deposit|list|fetch|gone, requip:fn:open, requip:pocket:<uuid>, requip:stampKey; /requip (/rq /wardrobe /wd /loadout), /requipadmin; kit @KITID@, page @PAGEID@");
}""".replace("@PAGEID@", PAGE_ID).replace("@FNS@", "\n".join('  br.put("%s", new @PKG@.WdFn(%d));' % (k_, m_) for k_, m_ in BRIDGE_FNS)))
M(plug, r"""
protected void shutdown() {
  try { if (TIMER instanceof java.util.concurrent.Future) ((java.util.concurrent.Future) TIMER).cancel(false); } catch (Throwable t) { }
  try { java.util.concurrent.ScheduledExecutorService rd = @PKG@.WdHop.READER; @PKG@.WdHop.READER = null; if (rd != null) rd.shutdownNow(); } catch (Throwable t1) { }   // 0.2.1 fixer
  try { int n = @PKG@.WdJournal.dropAll(); if (n > 0) @PKG@.WdLog.info("stop: " + n + " Requip journals closed (the engine saves every online player on a normal stop)"); } catch (Throwable t2) { }
  try { int n7 = @PKG@.WdSalv.dropAll(); if (n7 > 0) @PKG@.WdLog.info("stop: " + n7 + " salvage journals closed"); } catch (Throwable t7) { }   // 0.2.7
  try {
    java.util.Map br = @PKG@.WdLog.bridge();
    java.util.Iterator it = new java.util.ArrayList(br.keySet()).iterator();
    while (it.hasNext()) {
      Object k = it.next();
      Object f = br.get(k);
      if (f instanceof @PKG@.WdFn) br.remove(k, f);
      else if (k instanceof String && ((String) k).startsWith("requip:pocket:")) br.remove(k);
    }
  } catch (Throwable t3) { }
  try { @PKG@.CfgPub.shutdown(); } catch (Throwable t4) { }
  try { @PKG@.HubBar.removeAll(); } catch (Throwable t6) { }   // 0.2.6: the hub tab (only while it still holds OUR array)
  super.shutdown();
}""")

